-- G3 Task 3 fix round 2 — 6 rule packs POR MATERIA (pack_id = materia) para
-- las 6 materias SLP del catálogo (migración 20260804080000_g3_slp_materias.sql).
--
-- Hallazgo de la verificación viva de T9: el panel "Reglas aplicables al
-- orden del día" del ConvocatoriasStepper resuelve packs POR MATERIA
-- (rule-resolution.ts:310-317 — match estricto version.materia===input.materia
-- || version.packId===input.materia + alias canónico, SIN fallback a órgano).
-- Los 4 packs de órgano de G3 Task 3 (20260804070000_g3_garrigues_rule_packs.sql,
-- id/materia=GARR_*) nunca cubren ese camino: las 6 materias SLP mostraban
-- "No existe rule pack para la materia X" en rojo bloqueante en el flujo
-- estrella de la demo (la convocatoria real de la Junta de Socios 2026).
-- Aliasar esas 6 materias al pack de Junta habría enseñado mayorías
-- equivocadas a un mercantilista — inaceptable.
--
-- Cada payload es un clon estructural de GARR_JUNTA_SOCIOS v1.1.0
-- (20260805100000_g3_junta_socios_pack_v110.sql): misma convocatoria
-- (arts. 27.3/27.4 Estatutos), mismos quórums, acta, documentacion y
-- reglaEspecifica.canalAcuseLey2007 — heredado byte a byte de un payload que
-- ya satisface el contrato `isRulePackPayload` (convocatoria/constitucion/
-- votacion/documentacion como records; ConvocatoriasStepper.tsx:305-312).
-- Cambia únicamente: id/materia, clase (según materia_catalog.matter_class),
-- la mayoría real de votacion.mayoria.SL (la rama que effective-rule.ts lee
-- para tipoSocial SLP) según los Estatutos cotejados, y postAcuerdo/
-- plazosMateriales para las 2 materias no inscribibles. Las ramas SA/CONSEJO
-- de mayoria comparten la misma fórmula con referencia "materia exclusiva de
-- la forma SLP — rama no aplicable" (shape válido del Record cerrado,
-- contenido honesto: estas materias solo se evalúan como SLP).
--
-- EXCLUSION_SOCIO_ESTATUTARIA conserva además la rama anidada
-- votacion.mayoria.sociosProfesionalesExclusion de v1.1.0 (doble mayoría de
-- capital y socios profesionales, arts. 15/16 Ley 2/2007 — anidada a
-- propósito bajo votacion.mayoria: el extractor legacy
-- extractMajorityFromRulePackParams solo lee claves de primer nivel del
-- payload, no se toca). INTEGRACION_DESPACHO_AUMENTO_SIN_PREFERENCIA añade a
-- convocatoria.documentosObligatorios el informe del administrador único ex
-- art. 308 LSC (supresión del derecho de preferencia).
--
-- NOTA sobre discrepancia de citas: `materia_catalog.referencia_legal`
-- (20260804080000) cita para varias de estas materias artículos distintos de
-- los usados aquí en votacion.mayoria.SL.referencia (p. ej. EXCLUSION cita
-- "art. 21.1.e Estatutos" en el catálogo vs. "art. 30.2.g) Estatutos" en este
-- pack). No se concilia en esta migración — es contenido legal a resolver
-- por el Comité, no una decisión de ingeniería; se usan aquí las citas del
-- cotejo entregado para este fix, verbatim.
--
-- Los 4 packs de órgano de G3 Task 3 NO se tocan — siguen sirviendo el
-- camino Tramitador/órgano. Forward-only, idempotente (WHERE NOT EXISTS,
-- mismo patrón que las migraciones G3 anteriores). Espejo en
-- scripts/seed-garrigues-rule-packs.ts (buildSlpMateriaPayload +
-- SLP_MATERIA_PACKS), payload verificado por JSON round-trip contra ese
-- mismo objeto TS.

INSERT INTO public.rule_packs (id, tenant_id, materia, organo_tipo, descripcion)
SELECT 'ADMISION_SOCIO_CUOTA', '00000000-0000-0000-0000-000000000002'::uuid, 'ADMISION_SOCIO_CUOTA', 'JUNTA_GENERAL', 'Garrigues G3 — Admisión de socio de cuota (materia, clon GARR_JUNTA_SOCIOS v1.1.0)'
WHERE NOT EXISTS (SELECT 1 FROM public.rule_packs WHERE id = 'ADMISION_SOCIO_CUOTA');

