SELECT 'INTEGRACION_DESPACHO_AUMENTO_SIN_PREFERENCIA', '1.0.0', '{"id":"INTEGRACION_DESPACHO_AUMENTO_SIN_PREFERENCIA","materia":"INTEGRACION_DESPACHO_AUMENTO_SIN_PREFERENCIA","clase":"ESTRUCTURAL","organoTipo":"JUNTA_GENERAL","modosAdopcionPermitidos":["MEETING","UNIVERSAL"],"acta":{"tipoActaPorModo":{"MEETING":"ACTA_JUNTA","UNIVERSAL":"ACTA_JUNTA"},"requiereConformidadConjunta":false,"requiereTranscripcionLibroActas":true},"votacion":{"mayoria":{"SA":{"fuente":"SISTEMA","formula":"favor >= 2/3_votos_totales","referencia":"materia exclusiva de la forma SLP — rama no aplicable"},"SL":{"fuente":"LEY","formula":"favor >= 2/3_votos_totales","referencia":"art. 30.2.c) Estatutos; art. 308 LSC (supresión del derecho de preferencia — informe del órgano de administración)"},"CONSEJO":{"fuente":"SISTEMA","formula":"favor >= 2/3_votos_totales","referencia":"materia exclusiva de la forma SLP — rama no aplicable"}},"abstenciones":"no_cuentan","votoCalidadPermitido":false},"constitucion":{"quorum":{"SA_1a":{"valor":0.5,"fuente":"LEY","referencia":"art. 194.1 LSC"},"SA_2a":{"valor":0.25,"fuente":"LEY","referencia":"art. 194.1 LSC"},"SL":{"valor":0,"fuente":"LEY","referencia":"art. 198 LSC"},"CONSEJO":{"valor":"mayoria_miembros","fuente":"LEY","referencia":"art. 247.1 LSC"}}},"convocatoria":{"canales":{"SA":["BORME","WEB_INSCRITA"],"SL":["COMUNICACION_INDIVIDUAL_CON_ACUSE"],"SLP":["COMUNICACION_INDIVIDUAL_CON_ACUSE"]},"antelacionDias":{"SA":{"valor":30,"fuente":"LEY","referencia":"art. 176.1 LSC"},"SL":{"valor":15,"fuente":"ESTATUTOS","referencia":"arts. 27.4 Estatutos y 176 LSC (supletoria)"},"SLP":{"valor":15,"fuente":"ESTATUTOS","referencia":"arts. 27.4 Estatutos y 176 LSC (supletoria)"}},"contenidoMinimo":["Fecha hora y lugar","Orden del día","Texto íntegro de la propuesta cuando proceda"],"documentosObligatorios":[{"id":"propuesta","nombre":"Texto íntegro de la propuesta","condicion":"SIEMPRE"},{"id":"informe_admin","nombre":"Informe del administrador único","condicion":"SIEMPRE"},{"id":"informe_administrador_308","nombre":"Informe del administrador único sobre la supresión del derecho de preferencia (art. 308 LSC)","condicion":"SIEMPRE"}]},"documentacion":{"obligatoria":[{"id":"propuesta","nombre":"Propuesta íntegra"},{"id":"informe_admin_justificacion","nombre":"Informe justificativo del administrador único"},{"id":"derecho_informacion_287","nombre":"Derecho de información art. 287 LSC","condicion":"SIEMPRE"}],"ventanaDisponibilidad":{"dias":15,"fuente":"LEY"}},"postAcuerdo":{"inscribible":true,"instrumentoRequerido":"ESCRITURA","publicacionRequerida":true,"plazoInscripcion":{"dias":30,"fuente":"LEY","referencia":"art. 83 RRM (1 mes)"}},"plazosMateriales":{"inscripcion":{"plazo_dias":30,"fuente":"LEY","referencia":"art. 83 RRM"},"publicacion":["BORME"]},"reglaEspecifica":{"canalAcuseLey2007":{"codigo":"COMUNICACION_INDIVIDUAL_CON_ACUSE","referencia":"art. 27.3 Estatutos (comunicación individualizada y por escrito que asegure la recepción; también entrega en mano contra recibí); LSC supletoria","semanticaAcuse":"EAD_INTERPOSICION_ETIQUETADA","nota":"El acuse usa la semántica de interposición EAD Trust; no se afirma como capacidad de entrega/acuse probada (política 2026-07-21)."}}}'::jsonb, true, 'ACTIVE', CURRENT_DATE
WHERE NOT EXISTS (SELECT 1 FROM public.rule_pack_versions WHERE pack_id = 'INTEGRACION_DESPACHO_AUMENTO_SIN_PREFERENCIA' AND is_active = true);

DO $$
DECLARE v_missing integer;
BEGIN
  SELECT count(*) INTO v_missing FROM (
    VALUES ('ADMISION_SOCIO_CUOTA'), ('EXCLUSION_SOCIO_ESTATUTARIA'), ('CONTINUIDAD_SOCIO_POST_60'), ('NOMBRAMIENTO_ADMINISTRADOR_UNICO'), ('RETRIBUCION_PRESTACIONES_ACCESORIAS'), ('INTEGRACION_DESPACHO_AUMENTO_SIN_PREFERENCIA')
  ) AS t(id)
  WHERE NOT EXISTS (
    SELECT 1 FROM public.rule_packs rp
    JOIN public.rule_pack_versions v ON v.pack_id = rp.id AND v.is_active
    WHERE rp.id = t.id AND rp.tenant_id = '00000000-0000-0000-0000-000000000002'::uuid AND rp.organo_tipo = 'JUNTA_GENERAL'
  );
  IF v_missing <> 0 THEN
    RAISE EXCEPTION 'G3 Task 3 fix round 2 verificación fallida: % packs por-materia SLP sin pack activo bajo el tenant Garrigues', v_missing;
  END IF;

  -- Los 4 packs de órgano de G3 Task 3 no deben haberse tocado por esta migración.
  IF (SELECT count(*) FROM public.rule_packs WHERE tenant_id = '00000000-0000-0000-0000-000000000002'::uuid AND id LIKE 'GARR_%') <> 4 THEN
    RAISE EXCEPTION 'G3 Task 3 fix round 2 verificación fallida: los 4 packs de órgano GARR_* no deben cambiar de número';
  END IF;
END $$;
